// Generated by ChatGPT
// Models for data from USDA API

import Foundation

// Entire response returned from a USDA food search
struct USDAFoodSearchResponse: Decodable {
    
    let totalHits: Int? // Total number of matching foods
    let currentPage: Int? // Current page of results
    let totalPages: Int? // Total pages for that result
    
    let foods: [USDAFood]
}

// This will represent a food that is returned from USDA
struct USDAFood: Decodable, Identifiable {
    
    let fdcId: Int // USDA unique food identifier
    let description: String
    
    let dataType: String? // Foundation, SR Legacy, Survey Foods, Experiemntal, Branded
    let brandOwner: String?
    let ingredients: String?
    
    let foodNutrients: [USDAFoodNutrient]?
    
    // This is for when SwiftUI needs an id when displaying foods
    var id: Int {
        fdcId
    }
}

// Represents a singular nutrient entry for a food
struct USDAFoodNutrient: Decodable {
    
    let nutrientId: Int?
    let nutrientName: String?
    let nutrientNumber: String?
    let unitName: String?
    let value: Double?
}

// Full food info from USDA
struct USDAFoodDetail: Decodable {
    
    let fdcId: Int
    let description: String
    
    let dataType: String?
    let brandOwner: String?
    let ingredients: String?
    
    let servingSize: Double?
    let servingSizeUnit: String?
    let householdServingFullText: String?
    
    let foodNutrients: [USDAFoodDetailNutrient]?
    let foodPortions: [USDAFoodPortion]?
    
    let labelNutrients: USDALabelNutrients?
}

// Represents one nutrient from the full food info
struct USDAFoodDetailNutrient: Decodable {
    
    let amount: Double?
    let nutrient: USDANutrientInfo?
}

// Nutrient info inside USDAFoodDetailNutrient
struct USDANutrientInfo: Decodable {
    
    let id: Int?
    let number: String?
    let name: String?
    let unitName: String?
}

// Portion information for the foods
struct USDAFoodPortion: Decodable {
    
    let amount: Double?
    let gramWeight: Double?
    let modifier: String?
    let portionDescription: String?
    let measureUnit: USDAMeasureUnit?
}

// Specific unit used in a USDA food portion
struct USDAMeasureUnit: Decodable {
    
    let id: Int?
    let abbreviation: String?
    let name: String?
}

// Nutrition values shown on a branded food's label
struct USDALabelNutrients: Decodable {
    
    let calories: USDALabelNutrientValue?
    let protein: USDALabelNutrientValue?
    let carbohydrates: USDALabelNutrientValue?
    let fat: USDALabelNutrientValue?
}


// One nutrition value from the branded food label
struct USDALabelNutrientValue: Decodable {
    
    let value: Double?
}


